        r[u] = (s[u] == 'R');
        for (int v : g[u]) {
            if (v == p) continue;
            dfs1(v, u);
            sz[u] += sz[v];
            r[u] += r[v];
        }
    };
    dfs1(1, 0);

    int ans = 0;
    function<void(int, int)> dfs2 = [&](int u, int p) {
        for (int v : g[u]) {
